import os, json, re, sys, collections, datetime
sys.stdout.reconfigure(encoding="utf-8")
ROOT = os.path.expanduser(r"C:\Users\eric_rash\.claude\projects")
CUR = "0b0a1c5d-2552-45a2-a72a-ed068f84966b"
files = []
for dp, dn, fn in os.walk(ROOT):
    if "subagents" in dp.replace("\\", "/").split("/"):
        continue
    for f in fn:
        if f.endswith(".jsonl") and CUR not in f:
            p = os.path.join(dp, f)
            s = os.stat(p)
            if s.st_size >= 5120:
                files.append((s.st_mtime, p))
files.sort(reverse=True)
files = files[:30]

SKIP_PAT = re.compile(r"^\s*(<system-reminder>|<local-command-stdout>|<local-command-caveat>|<command-message>|Caveat:|\[Request interrupted|<task-notification>|<user-prompt-submit-hook>|This session is being continued|<bash-input>|<bash-stdout>)", re.S)

def summ(name, inp):
    if not isinstance(inp, dict): return ""
    if name in ("Bash", "PowerShell"): return (inp.get("command") or "")[:100].replace("\n", " ")
    for k in ("file_path", "path", "pattern", "skill", "query", "url", "description"):
        if k in inp: return str(inp[k])[:100]
    return ""

sessions = []
for mt, p in files:
    sid = os.path.basename(p)[:8]
    proj = os.path.basename(os.path.dirname(p))
    users, tools = [], []
    first_ts = None
    with open(p, encoding="utf-8", errors="replace") as fh:
        for line in fh:
            try: d = json.loads(line)
            except: continue
            ts = d.get("timestamp")
            if ts and not first_ts: first_ts = ts
            if d.get("isMeta") or d.get("isCompactSummary"): continue
            m = d.get("message") or {}
            if d.get("type") == "user" and m.get("role") == "user":
                c = m.get("content")
                texts = []
                if isinstance(c, str): texts = [c]
                elif isinstance(c, list):
                    texts = [b.get("text", "") for b in c if isinstance(b, dict) and b.get("type") == "text"]
                for t in texts:
                    cm = re.search(r"<command-name>(.*?)</command-name>", t)
                    if cm:
                        args = re.search(r"<command-args>(.*?)</command-args>", t, re.S)
                        users.append((ts, "CMD " + cm.group(1) + " " + (args.group(1)[:80] if args else "")))
                        continue
                    if SKIP_PAT.match(t): continue
                    t2 = re.sub(r"<system-reminder>.*?</system-reminder>", "", t, flags=re.S).strip()
                    if t2: users.append((ts, t2))
            elif d.get("type") == "assistant":
                c = m.get("content")
                if isinstance(c, list):
                    for b in c:
                        if isinstance(b, dict) and b.get("type") == "tool_use":
                            tools.append((b.get("name"), summ(b.get("name"), b.get("input"))))
    sessions.append(dict(sid=sid, proj=proj, mtime=datetime.datetime.fromtimestamp(mt).strftime("%Y-%m-%d"), start=(first_ts or "")[:10], users=users, tools=tools))

json.dump(sessions, open(os.path.join(os.path.dirname(__file__), "sessions.json"), "w", encoding="utf-8"))
print("N", len(sessions))
for s in sessions:
    print(s["sid"], s["start"], s["mtime"], s["proj"][-40:], "users", len(s["users"]), "tools", len(s["tools"]))

